        audit.append({'id':f'R{section:02}.{counts[section]:03}','section':section,'section_title':heading,'source_line':line_start,'requirement':text,'status':'Conditional / data required' if section in open_sections else 'Verified scope / implementation','evidence':section_refs[section],'finding':why.get(section,'Implementation/evidence present at referenced artifact; verify substantive limits rather than treating populated fields as business proof.'),'remaining_action':why.get(section,'Retain regression, source and artifact checks on refresh.'),'owner':'Named owner in evidence/monitoring register; author for presentation implementation','verification_basis':'Manual requirement review plus executable checks; section-level status conservatively inherited by its instruction blocks'})
