for lineno,line in enumerate(spec.splitlines(),1):
    match=re.match(r'## (\d+)\. (.*)',line)
    if match:flush();section=int(match[1]);heading=match[2];continue
    if line.startswith('# END MASTER PROMPT'):flush();section=0;break
    if not section:continue
    if not line.strip():flush();continue
    if re.match(r'^[-*] |^\d+\. |^\|',line):flush();line_start=lineno;block=[line];flush()
    elif line.startswith('### '):flush();line_start=lineno;block=[line];flush()
    else:
        if not block:line_start=lineno
        block.append(line)
